using CloudFileManager.Core;
using CloudFileManager.Web;
using System.Text.Json;
using System.Xml.Linq;
var passed = 0; var failed = 0;
void Check(bool b, string message = "assertion") { if (!b) throw new Exception(message); }
void Test(string name, Action test) { try { test(); passed++; Console.WriteLine("PASS " + name); } catch(Exception e) { failed++; Console.WriteLine("FAIL " + name + ": " + e); } }
JsonElement Json(object value) => JsonSerializer.SerializeToElement(value);
JsonElement State(WebWorkspace w) => Json(w.State());
JsonElement Act(WebWorkspace w, string action, string? id=null,string? tag=null,string? criterion=null,string? ext=null) => Json(w.Execute(new(action,id,tag,criterion,ext),_=>{}));
string Id(WebWorkspace w,string name)=>State(w).GetProperty("rows").EnumerateArray().Single(x=>x.GetProperty("name").GetString()==name).GetProperty("id").GetString()!;
void Select(WebWorkspace w,string name)=>Act(w,"select",Id(w,name));
int Count(WebWorkspace w,string tag)=>State(w).GetProperty("counts").GetProperty(tag).GetInt32();
Test("W01 clean seed",()=>{var w=new WebWorkspace();var s=State(w);Check(s.GetProperty("rows").GetArrayLength()==10);Check(s.GetProperty("logs").GetArrayLength()==0);Check(s.GetProperty("undoCount").GetInt32()==0&&s.GetProperty("redoCount").GetInt32()==0);Check(!s.GetProperty("canPaste").GetBoolean());Check(s.GetProperty("progress").GetProperty("status").GetString()=="idle");Check(s.GetProperty("criterion").GetString()=="Size"&&s.GetProperty("direction").GetString()=="Asc");Check(Count(w,"Personal")==2&&Count(w,"Work")==1&&Count(w,"Urgent")==0);});
Test("W02 exact capacities and display",()=>{var w=new WebWorkspace();var readme=State(w).GetProperty("rows").EnumerateArray().Single(x=>x.GetProperty("name").GetString()=="README.txt");Check(readme.GetProperty("sizeBytes").GetInt64()==500&&readme.GetProperty("details").GetString()!.StartsWith("0.5 KB"));Select(w,"README.txt");var s=Act(w,"size").GetProperty("state");Check(s.GetProperty("logs")[0].GetProperty("Text").GetString()!.Contains("500 B"));Check(s.GetProperty("progress").GetProperty("total").GetInt32()==1);});
Test("W03 sort controls do not alter tree/history",()=>{var w=new WebWorkspace();var root=FileSystemSession.Instance.Root;var order=root.Children.Select(x=>x.Id).ToArray();Act(w,"sort",criterion:"Size");Check(State(w).GetProperty("direction").GetString()=="Desc");Act(w,"sort",criterion:"Tag");Check(State(w).GetProperty("direction").GetString()=="Asc");Check(root.Children.Select(x=>x.Id).SequenceEqual(order));Check(State(w).GetProperty("undoCount").GetInt32()==0);});
Test("W04 tag key stable directions",()=>{var at=DateTimeOffset.UtcNow;var root=DirectoryNode.CreateRoot("r",at);var a=root.AddText("a",1,"x",at);var b=root.AddText("b",1,"x",at);var c=root.AddText("c",1,"x",at);var d=root.AddText("d",1,"x",at);var e=root.AddText("e",1,"x",at);var edit=new EditingSession(root);edit.AddTag(a,TagKind.Urgent);edit.AddTag(a,TagKind.Personal);edit.AddTag(b,TagKind.Personal);edit.AddTag(c,TagKind.Urgent);var strategy=new TagSortStrategy();Check(strategy.Order(root.Children,SortDirection.Asc).SequenceEqual(new FsNode[]{a,c,b,d,e}));Check(strategy.Order(root.Children,SortDirection.Desc).SequenceEqual(new FsNode[]{b,a,c,d,e}));});
Test("W05 tag noop retains redo/log",()=>{var w=new WebWorkspace();Act(w,"addTag",tag:"Work");Act(w,"undo");var before=State(w);Act(w,"addTag",tag:"Personal");var after=State(w);Check(after.GetProperty("redoCount").GetInt32()==1);Check(before.GetProperty("logs").GetArrayLength()==after.GetProperty("logs").GetArrayLength());});
Test("W06 badge remove does not change selection or descendants",()=>{var w=new WebWorkspace();var selected=State(w).GetProperty("selected").GetGuid();Act(w,"removeTag",Id(w,"2025備份"),"Personal");Check(State(w).GetProperty("selected").GetGuid()==selected);Check(Count(w,"Personal")==1&&Count(w,"Work")==1);Act(w,"undo");Check(Count(w,"Personal")==2);});
Test("W07 Paste file disabled/conflict atomic/redo",()=>{var w=new WebWorkspace();Act(w,"copy");Check(!State(w).GetProperty("canPaste").GetBoolean());Check(Act(w,"paste").TryGetProperty("error",out _));Select(w,"專案文件");Check(State(w).GetProperty("canPaste").GetBoolean());Act(w,"addTag",tag:"Work");Act(w,"undo");var before=TreeOperations.ToXml(FileSystemSession.Instance.Root);Check(Act(w,"paste").TryGetProperty("error",out _));Check(TreeOperations.ToXml(FileSystemSession.Instance.Root)==before);Check(State(w).GetProperty("redoCount").GetInt32()==1);});
Test("W08 Prototype snapshot independent and paste selection",()=>{var w=new WebWorkspace();Act(w,"copy");Act(w,"addTag",tag:"Urgent");Select(w,"個人筆記");var dest=State(w).GetProperty("selected").GetGuid();Act(w,"paste");Check(State(w).GetProperty("selected").GetGuid()==dest);var root=FileSystemSession.Instance.Root;var copy=root.Children.Single(n=>n.Name=="個人筆記").Children.Single(n=>n.Name=="API介面定義.docx");Check(!copy.Tags.Contains(TagKind.Urgent)&&copy.Tags.Contains(TagKind.Personal));Check(Count(w,"Personal")==3);});
Test("W09 delete undo selection and global count",()=>{var w=new WebWorkspace();Select(w,"個人筆記");Act(w,"delete");Check(State(w).GetProperty("selected").GetGuid()==FileSystemSession.Instance.Root.Id);Check(Count(w,"Personal")==1&&Count(w,"Work")==0);Act(w,"undo");Check(State(w).GetProperty("selected").GetGuid()==FileSystemSession.Instance.Root.Id);Check(Count(w,"Personal")==2&&Count(w,"Work")==1);});
Test("W10 ancestor fallback on Undo Paste",()=>{var w=new WebWorkspace();Select(w,"2025備份");Act(w,"copy");Select(w,"專案文件");var dest=State(w).GetProperty("selected").GetGuid();Act(w,"paste");var parent=FileSystemSession.Instance.Root.Children.Single(n=>n.Name=="專案文件");var copy=parent.Children.Single(n=>n.Name=="2025備份");Act(w,"select",copy.Children[0].Id.ToString());Act(w,"undo");Check(State(w).GetProperty("selected").GetGuid()==dest);});
Test("W11 visitor observed actual sequence and scope",()=>{var root=ReferenceTree.Create();var events=new List<TraversalProgress>();var source=new TraversalProgressSource();source.Progressed+=events.Add;var v=new SizeVisitor();FileSystemTraversal.Visit(root,v,progress:source);Check(events.Count==10);Check(events.Select(e=>e.Visited).SequenceEqual(Enumerable.Range(1,10)));Check(events.All(e=>e.Total==10));Check(v.TotalBytes==(200L+1+120+500+2048)*1024+500);var w=new WebWorkspace();var emissions=new List<object>();w.Execute(new("size"),emissions.Add);Check(Json(emissions[0]).GetProperty("progress").GetProperty("total").GetInt32()==1);});
Test("W12 XML regression contract and file scope",()=>{Check(XNode.DeepEquals(XElement.Parse(TreeOperations.ToXml(SampleTree.Create())), XElement.Load("tests/CloudFileManager.Tests/Fixtures/expected.xml")));var w=new WebWorkspace();var result=Act(w,"xml");var xml=result.GetProperty("download").GetProperty("content").GetString()!;Check(XElement.Parse(xml).Name.LocalName=="API介面定義_docx");Check(!State(w).GetProperty("logs")[0].GetProperty("Text").GetString()!.Contains("<"));Check(State(w).GetProperty("undoCount").GetInt32()==0);});
Test("W13 exact extension within scope, no filter",()=>{var w=new WebWorkspace();Act(w,"search",ext:"DOCX");var state=State(w);Check(state.GetProperty("searchSummary").GetString()=="找到 1 項");Check(state.GetProperty("rows").GetArrayLength()==10);Act(w,"search",ext:"doc");Check(State(w).GetProperty("searchSummary").GetString()=="找到 0 項");});
Test("W14 invalid search never fake scan",()=>{var w=new WebWorkspace();Check(Act(w,"search",ext:"*.docx").TryGetProperty("error",out _));Check(State(w).GetProperty("progress").GetProperty("status").GetString()=="idle");Check(State(w).GetProperty("undoCount").GetInt32()==0);});
Test("W15 Size distinguishes formatted equality",()=>{var at=DateTimeOffset.UtcNow;var r=DirectoryNode.CreateRoot("r",at);var a=r.AddText("512",512,"x",at);var b=r.AddText("500",500,"x",at);Check(SortedView.Children(r,new SizeSortStrategy(),SortDirection.Asc).SequenceEqual(new FsNode[]{b,a}));});
Guid[] Matches(WebWorkspace w)=>State(w).GetProperty("rows").EnumerateArray().Where(x=>x.GetProperty("searchMatch").GetBoolean()).Select(x=>x.GetProperty("id").GetGuid()).Order().ToArray();
Test("W16 search trace exact production visit order",()=>{var w=new WebWorkspace();Select(w,"我的根目錄");var events=new List<object>();w.Execute(new("search",Extension:".docx"),events.Add);var logs=State(w).GetProperty("logs").EnumerateArray().ToArray();var traces=logs.Where(x=>x.GetProperty("Kind").GetString()=="Trace").Select(x=>x.GetProperty("Text").GetString()).ToArray();Check(traces.SequenceEqual(new[]{"搜尋目錄: 我的根目錄","搜尋目錄: 個人筆記","搜尋目錄: 2025備份","掃描檔案: 會議記錄.docx","掃描檔案: 待辦清單.txt","搜尋目錄: 專案文件","掃描檔案: API介面定義.docx","掃描檔案: 需求規格書.docx","掃描檔案: 系統架構圖.png","掃描檔案: README.txt"}));Check(logs.Count(x=>x.GetProperty("Kind").GetString()=="Match")==3);Check(logs[^1].GetProperty("Text").GetString()=="找到 3 項");var stream=events.Select(Json).ToArray();Check(stream[0].GetProperty("type").GetString()=="searchReset");Check(stream.Count(x=>x.GetProperty("type").GetString()=="match")==3);Check(State(w).GetProperty("progress").GetProperty("name").GetString()=="README.txt");Check(State(w).GetProperty("progress").GetProperty("visited").GetInt32()==10);});
Test("W17 case insensitive replacement zero and identity sort",()=>{var w=new WebWorkspace();Select(w,"我的根目錄");var id=State(w).GetProperty("selected").GetGuid();Act(w,"search",ext:".docx");var first=Matches(w);Check(first.Length==3);Act(w,"search",ext:".DOCX");Check(Matches(w).SequenceEqual(first));Act(w,"sort",criterion:"Name");Check(Matches(w).SequenceEqual(first));Act(w,"search",ext:".png");Check(Matches(w).Length==1&&!first.Contains(Matches(w)[0]));Act(w,"search",ext:".unknown");Check(Matches(w).Length==0);Check(State(w).GetProperty("selected").GetGuid()==id&&State(w).GetProperty("rows").GetArrayLength()==10);});
Test("W18 highlight mutation removal never resurrects stale ids",()=>{var w=new WebWorkspace();Select(w,"我的根目錄");Act(w,"search",ext:"docx");Select(w,"API介面定義.docx");Act(w,"delete");Check(Matches(w).Length==2);Act(w,"undo");Check(Matches(w).Length==2);Act(w,"redo");Check(Matches(w).Length==2);});
Test("W19 search preserves domain history redo and last progress",()=>{var w=new WebWorkspace();Act(w,"addTag",tag:"Urgent");Act(w,"undo");var root=FileSystemSession.Instance.Root;var xml=TreeOperations.ToXml(root);Act(w,"search",ext:"docx");Check(State(w).GetProperty("redoCount").GetInt32()==1&&State(w).GetProperty("undoCount").GetInt32()==0);Check(TreeOperations.ToXml(root)==xml&&Count(w,"Urgent")==0);var before=State(w).GetProperty("progress").GetRawText();Select(w,"README.txt");Act(w,"sort",criterion:"Tag");Check(State(w).GetProperty("progress").GetRawText()==before);Act(w,"search",ext:"docx");Check(State(w).GetProperty("progress").GetProperty("total").GetInt32()==1&&Matches(w).Length==0);});
Test("W20 directory extension never matches",()=>{var at=DateTimeOffset.UtcNow;var root=DirectoryNode.CreateRoot("fake.docx",at);var file=root.AddText("actual.DOCX",1,"UTF8",at);var visitor=new ExtensionSearchVisitor(".docx");var events=new List<TraversalProgress>();var source=new TraversalProgressSource();source.Progressed+=events.Add;FileSystemTraversal.Visit(root,visitor,progress:source);Check(visitor.MatchedNodeIds.SequenceEqual(new[]{file.Id}));Check(events.Count==2&&events[0].NodeId==root.Id);});
Console.WriteLine($"RESULT {passed} passed; {failed} failed");return failed==0?0:1;
